asm_unified(
    ".include \"asm/macro.inc\"\n"
);
static inline void UpdateAnimalActorVisual(AnimalActor & actor)
{
    actor.sound_requested = false;
    if (actor.animation_countdown != 0)
        --actor.animation_countdown;
    else
        actor.animation_countdown = actor.animation_reload;
    EntityVisualController * visual = actor.unk_10.Get();
    if (visual != nullptr)
        visual->Update();
}

