DogActor::DogActor(GameObject * world, Dog * saved, Location * ball_location)
    : AnimalActor(world, Actor(*saved).location, ANIMATION_ID_0832),
      dog(saved), ball_location(ball_location), unk_40(false)
{
    if (saved->unk_20 == 5) {
        DogBallEntity * ball = static_cast<DogBallEntity *>(world->GetEntity(ENTITY_BALL));
        if (ball != 0) {
            if (ball->GetMap() == GetMap())
                ball->SetCarriedPosition(GetQ16X(), GetQ16Y(), GetAnim(), facing);
            else
                PauseMovement(0);
        }
    }
    SetBehavior(GetBehavior(), facing);
}


DogActor::~DogActor()
{
    if (unk_40) {
        x_q16 = saved_x * 65536;
        y_q16 = saved_y * 65536;
    }
    dog->SetLocation(GetLocation());
}


void DogActor::PauseMovement(u32 frames)
{
    if (dog->unk_20 == 5)
        DropBall();
    UnkBarnAnimal2C command;
    command.unk_00 = frames;
    command.unk_02 = 0;
    dog->method_0809BB48(&command);
    SetBehavior(0, facing);
}

bool IsDogActorCarryingBall(DogActor const * actor)
{
    return actor->dog->unk_20 == 5;
}

void DogActor::Update(EntityUpdateContext const & context)
{
    UpdateBehavior();
    UpdateAnimalActorVisual(*this);
}

void DogActor::UpdateWhileSuspended(EntityUpdateContext const & context)
{
    if (IsActorAxisMotionComplete(*this))
        UpdateBehavior();
    AActorEntity::UpdateWhileSuspended(context);
}

