void DogActor::SetBehavior(u32 behavior, u32 direction)
{
    if (behavior != 12 && unk_40)
        behavior = 12;
    SetAnimIfChanged(GetBehaviorAnimation(behavior));
    SetFacingIfChanged(direction);
    SetMovementSpeed(GetBehaviorMoveSpeed(behavior));
    if (behavior != last_behavior) {
        i32 effect = -1;
        if (behavior == 8)
            effect = 8;
        if (effect >= 0)
            StartActorSpriteEffect(*this, effect, true);
        else
            StopActorSpriteEffect(*this);
    }
    last_behavior = behavior;
}

u32 DogActor::GetBehavior() const
{
    switch (dog->unk_20) {
    default:
    case 4:
        return 3;
    case 0:
        return dog->unk_24.a.unk_02;
    case 1:
    case 2:
    case 3:
    case 5:
        return 2;
    case 6: {
        return dog->unk_24.a.unk_02 ? 11 : 2;
    }
    }
}


void DogActor::DropBall()
{
    DogBallEntity * ball = static_cast<DogBallEntity *>(game_object->GetEntity(ENTITY_BALL));
    if (ball != 0 && ball->carried) {
        i32 x = GetQ16X();
        i32 y = GetQ16Y();
        i32 distance = 8;
        u32 map = GetMap();
        GameObject * world = game_object;
        if (map != world->vfunc_14() && map != MAP_FARM)
            distance = 0;
        MapTerrainView const & terrain = world->GetMapTerrain(map);
        do {
            i32 offset = distance << 16;
            fu8 direction = facing;
            switch (direction) {
            case FACING_DOWN:
                ball->SetQ16X(x);
                ball->SetQ16Y(y + offset);
                break;
            case FACING_UP:
                ball->SetQ16X(x);
                ball->SetQ16Y(y - offset);
                break;
            case FACING_LEFT:
                ball->SetQ16X(x - offset);
                ball->SetQ16Y(y);
                break;
            case FACING_RIGHT:
                ball->SetQ16X(x + offset);
                ball->SetQ16Y(y);
                break;
            }
            --distance;
        } while (distance >= 0 && IsMapTerrainBoxBlocked(terrain, ball->GetBox()));
        ball->StopBeingCarried();
    }
}


bool DogActor::CanBeHit() const
{
    return !unk_40;
}


void DogActor::ReactToToolHit()
{
    if (unk_40)
        return;
    if (dog->unk_20 == 5)
        DropBall();
    AnimalReactionPayload command;
    command.bits.frames_remaining = 240 + RandomBelow(120);
    command.bits.retreat_frames = 60;
    command.bits.target_is_dog = 0;
    command.bits.retarget_frames = 0;
    dog->SetReaction(&command);
    SetBehavior(GetBehavior(), facing);
    dog->SubtractAffection(10);
    StartActorSpriteEffect(*this, 2, false);
    RequestSound(0xAA);
}


void DogActor::RespondToCall(Location const & origin)
{
    if (origin.GetMap() == GetMap() && dog->unk_20 != 5) {
        u32 affection = dog->GetAffection();
        i32 radius = CalculateAnimalResponseRadius(affection);
        i32 pixel_x = GetQ16X() >> 16;
        i32 dx = origin.GetX() - pixel_x;
        i32 pixel_y = GetQ16Y() >> 16;
        i32 dy = origin.GetY() - pixel_y;
        if (dx * dx + dy * dy <= radius * radius) {
            if (dog->unk_20 == 5)
                DropBall();
            AnimalApproachPayload command;
            command.frames_remaining = static_cast<u16>(480 + affection * 960 / 251);
            command.retarget_frames = 0;
            dog->SetApproachState(&command);
            if (!unk_40)
                SetBehavior(GetBehavior(), facing);
            dog->SetHasTalkedToday();
        }
    }
}


extern "C" void NotifyDogActorBallLanded(DogActor * actor, Location const & origin)
{
    if (actor->dog->GetGrowthStage() == Dog::STAGE_1 && origin.GetMap() == actor->GetMap()) {
        u32 adequacy = actor->dog->GetAdequacy();
        i32 radius = CalculateAnimalResponseRadius(adequacy);
        i32 pixel_x = actor->GetQ16X() >> 16;
        i32 dx = origin.GetX() - pixel_x;
        i32 pixel_y = actor->GetQ16Y() >> 16;
        i32 dy = origin.GetY() - pixel_y;
        if (dx * dx + dy * dy <= radius * radius) {
            actor->RequestSound(AUDIO_SFX_DOG_BARK);
            if (actor->dog->unk_20 == 5)
                actor->DropBall();
            AnimalApproachPayload command;
            command.frames_remaining = static_cast<u16>(480 + adequacy * 960 / 251);
            command.retarget_frames = 0;
            actor->dog->SetBallChaseState(&command);
            if (!actor->unk_40)
                actor->SetBehavior(actor->GetBehavior(), actor->facing);
            actor->dog->SetHasPlayedToday();
        }
    }
}

Box DogActor::GetBox() const
{
    return Box(-7, -4, 7, 5, x_q16 >> 16, y_q16 >> 16);
}

extern "C" u32 GetDogAuxRenderProfile(u32 growth_stage)
{
    return ENTITY_AUX_RENDER_SMALL_ANIMAL;
}

extern "C" u32 GetDogEffectOffsetKind(u32 growth_stage)
{
    switch (growth_stage)
    {
    case Dog::STAGE_0:
        return 6;
    case Dog::STAGE_1:
        return 8;
    }
    return 6;
}

