void HorseActor::SetBehavior(u32 behavior, u32 direction)
{
    if (behavior != 6 && unk_3D)
        behavior = 6;
    SetAnimIfChanged(GetBehaviorAnimation(behavior));
    SetFacingIfChanged(direction);
    SetMovementSpeed(GetBehaviorMoveSpeed(behavior));
    if (behavior != last_behavior && !rider_mounted) {
        i32 effect = -1;
        if (behavior == 4)
            effect = 8;
        if (effect >= 0)
            StartActorSpriteEffect(*this, effect, true);
        else
            StopActorSpriteEffect(*this);
    }
    last_behavior = behavior;
}

u32 HorseActor::GetBehavior() const
{
    switch (static_cast<i32>(horse->unk_20)) {
    default:
        return 0;
    case 0:
        return horse->movement.behavior;
    case 1:
        return 2;
    case 2:
        return 1;
    }
}


void HorseActor::vfunc_40()
{
    if (horse->unk_20 == 2) {
        HorseMovementState command;
        command.frames_remaining = 180;
        command.behavior = 0;
        horse->SetMovementState(&command);
        if (!unk_3D)
            SetBehavior(GetBehavior(), facing);
    }
}

bool HorseActor::CanBeBrushed() const
{
    return !horse->HasBeenBrushedToday();
}

void HorseActor::Brush()
{
    if (!horse->HasBeenBrushedToday()) {
        horse->AddAffection(1);
        horse->SetBrushed();
    }
    StartActorSpriteEffect(*this, 1, false);
    RequestSound(AUDIO_SFX_FOAL_NEIGH);
}


void HorseActor::RespondToPush(u32 direction, u32 frames)
{
    if (frames >= 60) {
        SetFacingIfChanged(direction);
        UnkBarnAnimal2C command;
        command.unk_00 = 60;
        horse->SetPushedState(&command);
        if (!unk_3D)
            SetBehavior(GetBehavior(), facing);
    }
}


void HorseActor::RespondToCall(Location const & origin)
{
    if (origin.GetMap() == GetMap()) {
        i32 radius = CalculateAnimalResponseRadius(horse->GetAffection());
        i32 pixel_x = GetQ16X() >> 16;
        i32 dx = origin.GetX() - pixel_x;
        i32 pixel_y = GetQ16Y() >> 16;
        i32 dy = origin.GetY() - pixel_y;
        if (dx * dx + dy * dy <= radius * radius) {
            AnimalApproachPayload command;
            command.frames_remaining = static_cast<u16>(480 + horse->GetAffection() * 960 / 256);
            command.retarget_frames = 0;
            horse->SetApproachState(&command);
            if (!unk_3D)
                SetBehavior(GetBehavior(), facing);
            horse->SetHasTalkedToday();
        }
    }
}


extern "C" u32 GetHorseAuxRenderProfile(u32 growth_stage);
extern "C" u32 GetHorseEffectOffsetKind(u32 growth_stage);

HorseSpriteController::HorseSpriteController(AActorEntity * owner, u32 growth_stage)
    : EntitySpriteController(owner, 5, 13, GetHorseAuxRenderProfile(growth_stage),
          GetHorseEffectOffsetKind(growth_stage), 0, false)
{
}

void HorseSpriteController::Draw(EntityDrawContext const & context)
{
    unk_8B = func_08032900(entity->GetMap(), entity->GetQ16X() >> 16, entity->GetQ16Y() >> 16);
    EntitySpriteController::Draw(context);
}

extern "C" u32 GetHorseAuxRenderProfile(u32 growth_stage)
{
    switch (growth_stage) {
    case Horse::STAGE_0:
        return ENTITY_AUX_RENDER_DEFAULT;
    case Horse::STAGE_1:
        return ENTITY_AUX_RENDER_LIVESTOCK;
    default:
        return ENTITY_AUX_RENDER_DEFAULT;
    }
}

extern "C" u32 GetHorseEffectOffsetKind(u32 growth_stage)
{
    switch (growth_stage) {
    case Horse::STAGE_0:
        return 14;
    case Horse::STAGE_1:
        return 15;
    }
    return 14;
}

