void ChickenActor::Update(EntityUpdateContext const & context)
{
    UpdateBehavior(context);
    UpdateAnimalActorVisual(*this);
}

void ChickenActor::UpdateWhileSuspended(EntityUpdateContext const & context)
{
    if (IsActorAxisMotionComplete(*this))
        UpdateBehavior(context);
    AActorEntity::UpdateWhileSuspended(context);
}

