void ChickenActor::SetBehavior(u32 behavior, u32 direction)
{
    SetAnimIfChanged(GetBehaviorAnimation(behavior));
    SetFacingIfChanged(direction);
    SetMovementSpeed(GetBehaviorMoveSpeed(behavior));
    if (behavior != last_behavior) {
        i32 effect = -1;
        u32 sleeping_behavior = livestock->GetGrowthStage() == Chicken::STAGE_0 ? 0 : 3;
        if (behavior == sleeping_behavior) {
            u32 hour = game_object->GetClock()->calendar.time.clock_hour;
            if (hour < 6 || hour > 20)
                effect = 8;
        }
        if (effect >= 0)
            StartActorSpriteEffect(*this, effect, true);
        else
            StopActorSpriteEffect(*this);
    }
    last_behavior = behavior;
}

u32 ChickenActor::GetBehavior() const
{
    switch (livestock->unk_24) {
    case 0:
        return livestock->unk_28.unk_02;
    case 1: {
        return (livestock->unk_28.unk_02 & 0x7F) ? 4 : 1;
    }
    default:
        return 0;
    }
}

u32 ChickenActor::GetBehaviorAnimation(u32 behavior) const
{
    return gChickenBehaviorAnimations[livestock->GetGrowthStage()][behavior];
}

i32 ChickenActor::GetBehaviorMoveSpeed(u32 behavior) const
{
    switch (behavior) {
    case 1:
        return 0x8000;
    default:
        return 0;
    }
}


bool ChickenActor::CanBeHit() const
{
    return true;
}

bool ChickenActor::IsSick() const
{
    return livestock->IsSick();
}

asm_unified(
    ".text\n"
);

bool ChickenActor::CanBeAttackedByWildDog() const
{
    bool allowed = false;
    if (location_map == MAP_FARM && !livestock->IsSick() && !livestock->IsUnhappy())
        allowed = true;
    return allowed;
}


void ChickenActor::ReactToToolHit()
{
    AnimalReactionPayload command;
    command.bits.frames_remaining = 240 + RandomBelow(120);
    command.bits.retreat_frames = 60;
    command.bits.target_is_dog = 0;
    command.bits.retarget_frames = 0;
    livestock->SetReaction(&command);
    SetBehavior(GetBehavior(), facing);
    livestock->SubtractAffection(10);
    livestock->SetUnhappy();
    StartActorSpriteEffect(*this, 2, false);
    RequestSound(livestock->GetGrowthStage() == Chicken::STAGE_1 ? AUDIO_SEQUENCE_166 : AUDIO_SEQUENCE_165);
}


void ChickenActor::CureSickness()
{
    livestock->ResetSick();
    if (livestock->IsUnhappy())
        livestock->ResetUnhappy();
}

asm_unified(
    ".text\n"
);


void ChickenActor::ReactToDogAttack()
{
    AnimalReactionPayload command;
    command.bits.frames_remaining = 240 + RandomBelow(120);
    command.bits.retreat_frames = 60;
    command.bits.target_is_dog = 1;
    command.bits.retarget_frames = 0;
    livestock->SetReaction(&command);
    SetBehavior(GetBehavior(), facing);
    livestock->SubtractAffection(10);
    livestock->SetUnhappy();
    StartActorSpriteEffect(*this, 2, false);
    RequestSound(livestock->GetGrowthStage() == Chicken::STAGE_1 ? AUDIO_SEQUENCE_166 : AUDIO_SEQUENCE_165);
}

Box ChickenActor::GetBox() const
{
    return Box(-7, -4, 7, 5, x_q16 >> 16, y_q16 >> 16);
}

extern "C" u32 GetChickenAuxRenderProfile(u32 growth_stage)
{
    return ENTITY_AUX_RENDER_SMALL_ANIMAL;
}

extern "C" u32 GetChickenEffectOffsetKind(u32 growth_stage)
{
    switch (growth_stage)
    {
    case Chicken::STAGE_0:
        return 6;
    case Chicken::STAGE_1:
        return 7;
    }
    return 6;
}

static inline void StartAnimalSpriteEffect(EntitySpriteController * controller,
    u32 index, EntitySpriteEffectMode mode)
{
    controller->effect.SetAnimation(index);
    controller->effect_mode = mode;
}

EntityVisualController * ChickenActor::CreateVisualController()
{
    Chicken::GrowthStage growth = livestock->GetGrowthStage();
    EntitySpriteController * controller = new EntitySpriteController(this, 2, 9,
        GetChickenAuxRenderProfile(growth), GetChickenEffectOffsetKind(growth), 0, false);
    u32 sleeping_behavior = livestock->GetGrowthStage() == Chicken::STAGE_0 ? 0 : 3;
    if (last_behavior == sleeping_behavior) {
        u32 hour = game_object->GetClock()->calendar.time.clock_hour;
        if (hour < 6 || hour > 20) {
            StartAnimalSpriteEffect(controller, 8, ENTITY_SPRITE_EFFECT_PERSISTENT);
        }
    }
    return controller;
}



CowActor::CowActor(GameObject * world, Cow * saved)
    : AnimalActor(world, Actor(*saved).location, 0x2B0)
{
    livestock = saved;

    SetBehavior(GetBehavior(), facing);
}

CowActor::~CowActor()
{
    livestock->SetLocation(GetLocation());
}


void CowActor::PauseMovement(u32 frames)
{
    BarnAnimalMovementState command;
    command.frames_remaining = frames;
    command.behavior = 0;
    livestock->SetMovementState(&command);
    SetBehavior(GetBehavior(), facing);
}

