SheepActor::SheepActor(GameObject * world, Sheep * saved)
    : AnimalActor(world, Actor(*saved).location, 0x921)
{
    livestock = saved;

    SetBehavior(GetBehavior(), facing);
}

SheepActor::~SheepActor()
{
    livestock->SetLocation(GetLocation());
}


void SheepActor::PauseMovement(u32 frames)
{
    BarnAnimalMovementState command;
    command.frames_remaining = frames;
    command.behavior = 0;
    livestock->SetMovementState(&command);
    SetBehavior(GetBehavior(), facing);
}

