void SheepActor::SetBehavior(u32 behavior, u32 direction)
{
    SetAnimIfChanged(GetBehaviorAnimation(behavior));
    SetFacingIfChanged(direction);
    SetMovementSpeed(GetBehaviorMoveSpeed(behavior));
    if (behavior != last_behavior) {
        i32 effect = -1;
        if (behavior == 4)
            effect = 8;
        if (effect >= 0)
            StartActorSpriteEffect(*this, effect, true);
        else
            StopActorSpriteEffect(*this);
    }
    last_behavior = behavior;
}

u32 SheepActor::GetBehavior() const
{
    return GetBarnAnimalBehavior(*livestock);
}


u32 SheepActor::GetBehaviorAnimation(u32 behavior) const
{
    bool pregnant = false;
    if (livestock->IsPregnant())
        pregnant = livestock->GetDaysPregnant() != 0;
    return gSheepBehaviorAnimations[pregnant ? 3 : livestock->IsSheared() ? 2 : livestock->GetGrowthStage()][behavior];
}

i32 SheepActor::GetBehaviorMoveSpeed(u32 behavior) const
{
    switch (behavior) {
    case 1:
        return 0x8000;
    default:
        return 0;
    }
}


void SheepActor::RespondToBell(Location const & origin)
{
    if (origin.GetMap() == GetMap() && !livestock->IsPregnant()) {
        i32 radius = CalculateAnimalResponseRadius(livestock->GetAffection());
        i32 pixel_x = GetQ16X() >> 16;
        i32 dx = origin.GetX() - pixel_x;
        i32 pixel_y = GetQ16Y() >> 16;
        i32 dy = origin.GetY() - pixel_y;
        if (dx * dx + dy * dy <= radius * radius) {
            u32 chance;
            if (livestock->IsSick())
                chance = 30;
            else
                chance = livestock->IsUnhappy() ? 70 : 100;
            if (RandomBelow(100) < chance) {
                AnimalApproachPayload command;
                command.frames_remaining = static_cast<u16>(480 + livestock->GetAffection() * 960 / 256);
                command.retarget_frames = 0;
                livestock->SetApproachState(&command);
                SetBehavior(GetBehavior(), facing);
            }
        }
    }
}


void SheepActor::vfunc_40()
{
    if (livestock->state == BarnAnimal::STATE_PUSHED) {
        BarnAnimalMovementState command;
        command.frames_remaining = 180;
        command.behavior = 0;
        livestock->SetMovementState(&command);
        SetBehavior(GetBehavior(), facing);
    }
}

bool SheepActor::CanBeHit() const
{
    return true;
}

bool SheepActor::CanReceiveSheepMiraclePotion() const
{
    return !livestock->IsPregnant() && livestock->CanBeMadePregnant();
}

bool SheepActor::CanBeBrushed() const
{
    return !livestock->HasBeenBrushedToday();
}

bool SheepActor::CanBeSheared() const
{
    return livestock->CanBeSheared();
}


bool SheepActor::IsSick() const
{
    return livestock->IsSick();
}

asm_unified(
    ".text\n"
);

bool SheepActor::CanBeAttackedByWildDog() const
{
    bool allowed = false;
    if (location_map == MAP_FARM && !livestock->IsSick() && !livestock->IsUnhappy())
        allowed = true;
    return allowed;
}


void SheepActor::ReactToToolHit()
{
    if (!livestock->IsPregnant()) {
        AnimalReactionPayload command;
        command.bits.frames_remaining = 240 + RandomBelow(120);
        command.bits.retreat_frames = 60;
        command.bits.target_is_dog = 0;
        command.bits.retarget_frames = 0;
        livestock->SetReaction(&command);
        SetBehavior(GetBehavior(), facing);
    }
    livestock->SubtractAffection(10);
    livestock->SetUnhappy();
    StartActorSpriteEffect(*this, 0, false);
    RequestSound(AUDIO_SEQUENCE_164);
}

void SheepActor::StartSheepPregnancy()
{
    livestock->StartPregnancy();
}

void SheepActor::Brush()
{
    if (!livestock->HasBeenBrushedToday()) {
        livestock->AddAffection(1);
        livestock->SetBrushed();
    }
    if (livestock->IsUnhappy() && RandomBelow(100) < 30)
        livestock->ResetUnhappy();
    if (!livestock->IsSick()) {
        StartActorSpriteEffect(*this, 1, false);
        RequestSound(AUDIO_SFX_SHEEP_BLEAT);
    }
}


Livestock::ProductRank SheepActor::Shear()
{
    StartActorSpriteEffect(*this, 1, false);
    RequestSound(AUDIO_SFX_SHEEP_BLEAT);
    Livestock::ProductRank rank = livestock->ConsumeProduct();
    SetAnimIfChanged(GetBehaviorAnimation(last_behavior));
    return rank;
}


void SheepActor::CureSickness()
{
    livestock->ResetSick();
    if (livestock->IsUnhappy())
        livestock->ResetUnhappy();
}

asm_unified(
    ".text\n"
);


void SheepActor::ReactToDogAttack()
{
    if (!livestock->IsPregnant()) {
        AnimalReactionPayload command;
        command.bits.frames_remaining = 240 + RandomBelow(120);
        command.bits.retreat_frames = 60;
        command.bits.target_is_dog = 1;
        command.bits.retarget_frames = 0;
        livestock->SetReaction(&command);
        SetBehavior(GetBehavior(), facing);
    }
    livestock->SubtractAffection(10);
    livestock->SetUnhappy();
    StartActorSpriteEffect(*this, 0, false);
    RequestSound(AUDIO_SEQUENCE_164);
}


void SheepActor::RespondToPush(u32 direction, u32 frames)
{
    if (!livestock->IsPregnant() && frames >= 60) {
        SetFacingIfChanged(direction);
        UnkBarnAnimal2C command;
        command.unk_00 = 60;
        livestock->SetPushedState(&command);
        SetBehavior(GetBehavior(), facing);
    }
}

extern "C" u32 GetSheepAuxRenderProfile(u32 growth_stage)
{
    switch (growth_stage)
    {
    case Sheep::STAGE_0:
        return ENTITY_AUX_RENDER_DEFAULT;
    case Sheep::STAGE_1:
        return ENTITY_AUX_RENDER_LIVESTOCK;
    default:
        return ENTITY_AUX_RENDER_DEFAULT;
    }
}

extern "C" u32 GetSheepEffectOffsetKind(u32 growth_stage)
{
    switch (growth_stage)
    {
    case Sheep::STAGE_0:
        return 0xA;
    case Sheep::STAGE_1:
        return 0xD;
    }
    return 0xA;
}

